// ***************
// Filename: intc_top.sv
// Author: FPGA Cores 4 U
// Description: intc with its AXI4-Lite register interface, the block designs
//   and testbenches instantiate: the register map intc_regs (u_regs,
//   src/include/intc_regs.sv, ID "INTC", VERSION and DATE at 0x00-0x08, the
//   registers from 0x10) and the logic intc (u_core, src/intc.sv), joined by
//   their register ports (cfg_* to the logic, sts_* back). Generated by
//   ip/scripts/regmap_gen.py from intc_regs.json and the ports of intc:
//   regenerate after changing either. Clock - aclk. Reset - synchronous
//   active low aresetn.
// Date: 2026-10-12
module intc_top #(
  parameter int NUM_IRQ = 16
) (
  input  logic               aclk,
  input  logic               aresetn,
  input  logic [7:0]         s_axil_awaddr,
  input  logic               s_axil_awvalid,
  output logic               s_axil_awready,
  input  logic [31:0]        s_axil_wdata,
  input  logic [3:0]         s_axil_wstrb,
  input  logic               s_axil_wvalid,
  output logic               s_axil_wready,
  output logic [1:0]         s_axil_bresp,
  output logic               s_axil_bvalid,
  input  logic               s_axil_bready,
  input  logic [7:0]         s_axil_araddr,
  input  logic               s_axil_arvalid,
  output logic               s_axil_arready,
  output logic [31:0]        s_axil_rdata,
  output logic [1:0]         s_axil_rresp,
  output logic               s_axil_rvalid,
  input  logic               s_axil_rready,
  input  logic [NUM_IRQ-1:0] irq_i,
  output logic               irq_o
);
  // register ports between the register map and the logic
  logic [NUM_IRQ-1:0] cfg_enable;
  logic [NUM_IRQ-1:0] cfg_edge_type;
  logic [NUM_IRQ-1:0] cfg_active_low;
  logic [NUM_IRQ-1:0] cfg_pending;
  logic cfg_pending_wr;
  logic [NUM_IRQ-1:0] sts_pending;
  logic [NUM_IRQ-1:0] cfg_soft_set;
  logic cfg_soft_set_wr;
  logic [31:0] sts_vector;
  logic [NUM_IRQ-1:0] sts_masked;

  intc_regs #(
    .NUM_IRQ(NUM_IRQ)
  ) u_regs (
    .aclk,
    .aresetn,
    .s_axil_awaddr,
    .s_axil_awvalid,
    .s_axil_awready,
    .s_axil_wdata,
    .s_axil_wstrb,
    .s_axil_wvalid,
    .s_axil_wready,
    .s_axil_bresp,
    .s_axil_bvalid,
    .s_axil_bready,
    .s_axil_araddr,
    .s_axil_arvalid,
    .s_axil_arready,
    .s_axil_rdata,
    .s_axil_rresp,
    .s_axil_rvalid,
    .s_axil_rready,
    .enable_o(cfg_enable),
    .enable_wr_o(),
    .edge_type_o(cfg_edge_type),
    .edge_type_wr_o(),
    .active_low_o(cfg_active_low),
    .active_low_wr_o(),
    .pending_o(cfg_pending),
    .pending_wr_o(cfg_pending_wr),
    .pending_i(sts_pending),
    .soft_set_o(cfg_soft_set),
    .soft_set_wr_o(cfg_soft_set_wr),
    .vector_i(sts_vector),
    .masked_i(sts_masked)
  );
  intc #(
    .NUM_IRQ(NUM_IRQ)
  ) u_core (
    .aclk,
    .aresetn,
    .irq_i,
    .irq_o,
    .cfg_enable,
    .cfg_edge_type,
    .cfg_active_low,
    .cfg_pending,
    .cfg_pending_wr,
    .sts_pending,
    .cfg_soft_set,
    .cfg_soft_set_wr,
    .sts_vector,
    .sts_masked
  );
endmodule
